using Forge.LiveDirector.Authoring;
using Forge.Network.Authoring;
using Forge.Network.Operations;
using Forge.Network.Sessions;
namespace Forge.Mcp.LiveDirector;

public sealed record LiveDirectorOperationsResource(bool Found, LiveDirectorOperationsProfile? Profile, IReadOnlyList<NetworkDiagnostic> Diagnostics); public sealed record LiveDirectorOperationsPlanRequest(Guid PlanId, long BaseRevision, string ActorId, NetworkRole Role, NetworkAuthorityScope Scope, LiveDirectorOperationsProfile Candidate); public sealed record LiveDirectorOperationsPlanResult(bool Succeeded, string? PlanId, bool Applied, LiveDirectorOperationsProfile Profile, string SemanticDiff, IReadOnlyList<NetworkDiagnostic> Diagnostics, IReadOnlyList<string> Audit);
public sealed class LiveDirectorOperationsAgentService { private readonly LiveDirectorOperationsHistory h; private readonly Dictionary<string, LiveDirectorOperationsPlanRequest> p = new(StringComparer.Ordinal); private readonly List<string> a = []; public LiveDirectorOperationsAgentService() : this(LiveDirectorOperationsProfile.CreateDefault("mcp:r129")) { } public LiveDirectorOperationsAgentService(LiveDirectorOperationsProfile x) => h = new(x); public LiveDirectorOperationsResource Get(Guid? id = null, string? search = null) { var x = h.Current; var found = (id is null || id == x.Id) && (string.IsNullOrWhiteSpace(search) || x.Provenance.Contains(search, StringComparison.OrdinalIgnoreCase) || "search script variable scene fog".Contains(search, StringComparison.OrdinalIgnoreCase)); return found ? new(true, x, []) : new(false, null, [new("LIVE_OPS_NOT_FOUND", "/liveDirector/operations", "No profile matched.", id)]); } public LiveDirectorOperationsPlanResult Plan(LiveDirectorOperationsPlanRequest q) { if (q.Scope != NetworkAuthorityScope.Server) return F([new("LIVE_OPS_SCOPE_INVALID", "/liveDirector/operations/authorityScope", "Server required.", q.Candidate.Id)]); var r = h.Execute(C(q, false)); a.Add(r.AuditEntry); if (!r.Succeeded) return new(false, null, false, r.Profile, r.SemanticDiff, r.Diagnostics, a.ToArray()); var id = q.PlanId.ToString("D"); p[id] = q; return new(true, id, false, r.Profile, r.SemanticDiff, r.Diagnostics, a.ToArray()); } public LiveDirectorOperationsPlanResult Apply(string id) { if (!p.Remove(id, out var q)) return F([new("LIVE_OPS_PLAN_UNKNOWN", "/liveDirector/operations/planId", "Unknown.")]); var r = h.Execute(C(q, true)); a.Add(r.AuditEntry); return new(r.Succeeded, id, r.Applied, r.Profile, r.SemanticDiff, r.Diagnostics, a.ToArray()); } public LiveDirectorOperationsPlanResult Revert(string actor, NetworkRole role) { var r = h.Undo(actor, role); a.Add(r.AuditEntry); return new(r.Succeeded, null, r.Applied, r.Profile, r.SemanticDiff, r.Diagnostics, a.ToArray()); } private LiveDirectorOperationsPlanResult F(IReadOnlyList<NetworkDiagnostic> d) => new(false, null, false, h.Current, "no changes", d, a.ToArray()); private static LiveDirectorOperationsCommand C(LiveDirectorOperationsPlanRequest q, bool apply) => new(q.PlanId, 1, q.Candidate.Provenance, q.BaseRevision, q.ActorId, q.Role, apply, q.Candidate); }
